// Simple Asteroid Dodge game
// Canvas with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // Ship (triangle) definition
  const ship = {
    x: 80,
    y: height / 2,
    size: 20,
    speed: 4,
  };

  // Input handling
  const keys = { ArrowUp: false, ArrowDown: false };
  window.addEventListener('keydown', e => { if (e.key in keys) keys[e.key] = true; });
  window.addEventListener('keyup', e => { if (e.key in keys) keys[e.key] = false; });

  // Asteroids (circles)
  const asteroids = [];
  const asteroidFreq = 90; // frames between spawns (approx)
  let frameCount = 0;
  let score = 0;
  const startTime = performance.now();

  function spawnAsteroid() {
    const size = Math.random() * 30 + 10;
    const speed = Math.random() * 2 + 2; // leftward speed
    asteroids.push({
      x: width + size,
      y: Math.random() * height,
      r: size,
      speed,
    });
  }

  function update() {
    // Move ship
    if (keys.ArrowUp) ship.y -= ship.speed;
    if (keys.ArrowDown) ship.y += ship.speed;
    // Wrap vertically
    if (ship.y < 0) ship.y = height;
    if (ship.y > height) ship.y = 0;

    // Spawn asteroids
    if (frameCount % asteroidFreq === 0) spawnAsteroid();
    frameCount++;

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x -= a.speed;
      if (a.x + a.r < 0) asteroids.splice(i, 1);
    }

    // Collision detection (approximate ship as circle)
    const shipR = ship.size * 0.6;
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      if (dx * dx + dy * dy < (a.r + shipR) ** 2) {
        // Game over
        cancelAnimationFrame(animId);
        ctx.fillStyle = 'red';
        ctx.font = '48px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over', width / 2, height / 2);
        return;
      }
    }
  }

  function draw() {
    // Clear background (starfield simple)
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, width, height);
    // Draw ship (triangle pointing right)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y);
    ctx.lineTo(ship.x - ship.size, ship.y - ship.size / 2);
    ctx.lineTo(ship.x - ship.size, ship.y + ship.size / 2);
    ctx.closePath();
    ctx.fill();
    // Draw asteroids
    ctx.fillStyle = '#888';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // Draw score
    score = Math.floor((performance.now() - startTime) / 100);
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText(`Score: ${score}`, 80, 30);
  }

  let animId;
  function loop() {
    update();
    draw();
    animId = requestAnimationFrame(loop);
  }
  loop();
})();
